"""Pixel Arena level pathing: bots walk a tile map painted in primary colors."""

import heapq

Cell = tuple[int, int]  # (row, col)


def find_path(grid: list[str]) -> list[Cell] | None:
    """Cheapest 4-neighbour path from 'S' to 'G', both inclusive.

    '.' floor costs 1 to enter, 'D' door costs 3, '#' is a wall, 'S'/'G' cost 1.
    Return None when G is unreachable.
    """
    rows = len(grid)
    cols = len(grid[0]) if rows else 0
    start = goal = None
    for r, row in enumerate(grid):
        for c, ch in enumerate(row):
            if ch == 'S':
                start = (r, c)
            elif ch == 'G':
                goal = (r, c)
    if start is None or goal is None:
        return None

    def cost(ch: str) -> int:
        if ch == 'D':
            return 3
        return 1  # '.', 'S', 'G'

    best = {start: 0}
    prev: dict[Cell, Cell] = {}
    heap = [(0, start)]
    while heap:
        d, cell = heapq.heappop(heap)
        if cell == goal:
            path = [cell]
            while path[-1] != start:
                path.append(prev[path[-1]])
            return path[::-1]
        if d > best.get(cell, float('inf')):
            continue
        r, c = cell
        for nr, nc in ((r - 1, c), (r + 1, c), (r, c - 1), (r, c + 1)):
            if not (0 <= nr < rows and 0 <= nc < cols):
                continue
            ch = grid[nr][nc]
            if ch == '#':
                continue
            nd = d + cost(ch)
            if nd < best.get((nr, nc), float('inf')):
                best[(nr, nc)] = nd
                prev[(nr, nc)] = cell
                heapq.heappush(heap, (nd, (nr, nc)))
    return None

